# Primary Keys
# =============================================================================

@pytest.mark.infra
@pytest.mark.infra_postgres
class TestInfraPostgresPrimaryKeys:
    """Validate that primary key constraints match."""

    @pytest.mark.parametrize("model_class", MODELS, ids=lambda m: m.__name__)
    def test_infra_postgres_primary_keys_match(self, pg_engine, model_class):
        table_name = model_class.__tablename__
        db_tables = _get_db_table_names(pg_engine)
        if table_name not in db_tables:
            pytest.skip(f"Table '{table_name}' does not exist")

        model_pk = _get_model_pk(model_class)
        db_pk = _get_db_pk(pg_engine, table_name)

        assert model_pk == db_pk, (
            f"Primary key mismatch in {model_class.__name__} ({table_name}): "
            f"model={sorted(model_pk)}, db={sorted(db_pk)}"
        )


# =============================================================================
# Foreign Keys
# =============================================================================

@pytest.mark.infra
@pytest.mark.infra_postgres
class TestInfraPostgresForeignKeys:
    """Validate that foreign key constraints exist in the real DB."""

    @pytest.mark.parametrize("model_class", MODELS, ids=lambda m: m.__name__)
    def test_infra_postgres_foreign_keys_exist(self, pg_engine, model_class):
        table_name = model_class.__tablename__
        db_tables = _get_db_table_names(pg_engine)
        if table_name not in db_tables:
            pytest.skip(f"Table '{table_name}' does not exist")

        model_fks = _get_model_fks(model_class)
        if not model_fks:
            pytest.skip(f"Model {model_class.__name__} has no foreign keys")

        db_fks = _get_db_fks(pg_engine, table_name)
        db_fk_cols = set()
        for fk in db_fks:
            db_fk_cols.update(fk["constrained_columns"])

        missing_fk_cols = set(model_fks.keys()) - db_fk_cols
        assert not missing_fk_cols, (
            f"Foreign key constraints missing in {model_class.__name__} ({table_name}): "
            f"model defines FKs on {sorted(model_fks.keys())} but DB only has FKs on "
            f"{sorted(db_fk_cols)}. Missing: {sorted(missing_fk_cols)}"
        )


# =============================================================================
# Orphaned Column Detection (warn only)
# =============================================================================

@pytest.mark.infra
@pytest.mark.infra_postgres
class TestInfraPostgresExtraDbColumns:
    """Detect columns in DB that are NOT in the model (possible orphaned columns)."""

    @pytest.mark.parametrize("model_class", MODELS, ids=lambda m: m.__name__)
    def test_infra_postgres_no_orphaned_columns(self, pg_engine, model_class):
        table_name = model_class.__tablename__
        db_tables = _get_db_table_names(pg_engine)
        if table_name not in db_tables:
            pytest.skip(f"Table '{table_name}' does not exist")

        model_cols = _get_model_columns(model_class)
        db_cols = set(_get_db_columns(pg_engine, table_name).keys())

        extra = db_cols - model_cols
        if extra:
            import warnings
            warnings.warn(
                f"Table '{table_name}' has columns not in model {model_class.__name__}: "
                f"{sorted(extra)}. These may be orphaned or managed outside SQLAlchemy.",
                stacklevel=2,
            )
